/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A63 staging · exact frozen manifest limp–loan (80 lemmas). */
'use strict';
const D=globalThis.RA.D;
const Q=(prompt,answer,wrong1,wrong2,explain)=>({prompt,answer,options:[answer,wrong1,wrong2],explain,errorType:'meaning',type:'辨义与用法'});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const quizSenses={limp:[1,2,3,3],line:[1,2,3,4],'line-up':[1,2,1,1],linen:[1,2,1,1],liner:[1,2,3,1],ling:[1,2,1,1],linger:[1,2,1,1],lingual:[1,2,1,1],linguistic:[1,2,1,1],link:[1,2,3,4],liquid:[1,2,3,3],liquidate:[1,1,1,2],liquor:[1,1,2,1],list:[1,1,3,2],listen:[1,1,2,1],listless:[1,1,2,1],liter:[1,1,1,2],literacy:[1,2,1,1],literal:[1,2,3,1],literally:[1,2,1,1],literary:[1,1,2,3],literate:[1,2,1,1],lithe:[1,1,2,1],lithograph:[1,1,2,1],lithosphere:[1,2,1,1],litter:[1,2,3,4],little:[1,2,3,4],live:[1,2,3,4],livelihood:[1,2,2,1],lively:[1,2,1,2],liver:[1,1,2,1],livestock:[1,2,1,2],'living-room':[1,1,1,2],lizard:[1,1,2,1],load:[1,2,3,4],loaf:[1,2,3,1],loam:[1,1,1,2],loan:[1,2,3,1]};
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[c],mistakes:[m],quiz:qs.map((q,i)=>({...q,id:w+'.q'+(i+1),senseId:w+'.s'+(quizSenses[w]?.[i]||Number(c.senseId.split('.s')[1]))}))});

P('limp','Limp as a verb is recorded in English for walking unevenly; the related adjective describes something soft, slack, or lacking strength.',C('limp.s1','运动损伤','After twisting his ankle, the midfielder limped off the field while a teammate called for the trainer.','扭伤脚踝后，这名中场球员一瘸一拐地离开球场，队友则呼叫了理疗师。','After twisting his ankle / the midfielder limped off the field / while a teammate called / for the trainer.','limped 是不及物动词，表示因腿脚受伤而跛行；off the field 表示离开场地。','受伤后行走困难，符合 s1。'),M('The player limped off the field by sprinting evenly on both legs without pain or difficulty.','The player walked with difficulty because his ankle was hurt.','双腿均匀冲刺且没有不适，与 limping 的跛行状态相反。'),[Q('To limp off the field is to?','walk away with difficulty because of an injury','run evenly at full speed','cover the field with a soft layer','limp 作动词表示跛行。'),Q('A person’s limp is?','an uneven way of walking','a long thin mark on a page','a connection between two towns','limp 也可作名词指跛行步态。'),Q('If flowers look limp, they are?','soft and lacking strength','bright and sharply defined','full of lime compounds','形容词 limp 可表示植物萎软。'),Q('Which phrase is natural?','a limp handshake','a limp handshake that is firm and forceful','limp the flowers into a line','a limp handshake 指软弱无力的握手。')]);
P('limpid','Limpid comes from French limpide and Latin limpidus, “clear, transparent”; figuratively it can describe lucid language.',C('limpid.s1','山泉观察','The pebbles remained visible through the limpid pool even where the water was several feet deep.','即使水深达数英尺，透过清澈的水潭仍能看见卵石。','The pebbles remained visible / through the limpid pool / even where the water / was several feet deep.','limpid 修饰 pool，表示水清澈透明；even where 强调较深处仍可见。','水透明到能看见底部卵石，符合 s1。'),M('The pool was limpid although thick mud made the water opaque and hid everything below the surface.','The pool was muddy and opaque rather than limpid.','浑浊不透明的水与 limpid 的清澈义相反。'),[Q('Limpid water is?','clear and transparent','thick with mud and opaque','slow because someone is injured','limpid 指清澈透明的。'),Q('What could visitors see through the pool?','pebbles below the water','nothing because the pool was opaque','a line-up of suspects','清澈的水让卵石可见。'),Q('Limpid prose is prose that is?','lucid and easy to understand','soft and weak like a limp flower','full of calcium compounds','limpid 可比喻表达清晰易懂。'),Q('The Latin source limpidus meant?','clear or transparent','a short row of people','a family line of ancestors','词源 limpidus 表示清澈透明。')]);
P('limping','Limping is the -ing form of limp and also an adjective describing someone who walks with difficulty because of an injured leg.',C('limping.s1','诊所候诊','The limping hiker sat down outside the clinic while the nurse brought an ice pack for his ankle.','这名跛行的徒步者在诊所外坐下，护士则给他的脚踝拿来冰袋。','The limping hiker sat down / outside the clinic / while the nurse brought / an ice pack for his ankle.','limping 前置修饰 hiker，说明其因腿伤而跛行；while 表示护士同时提供帮助。','徒步者受伤后走路困难，符合 s1。'),M('The limping hiker crossed the room without difficulty on a perfectly healthy leg.','The hiker limped because an injured leg made walking difficult.','毫无困难地行走与 limping 不符。'),[Q('A limping hiker is someone who?','walks with difficulty because of an injured leg','walks briskly with two healthy legs','cannot understand clear language','limping 描述因腿伤而跛行。'),Q('Why did the nurse bring an ice pack?','the hiker had hurt his ankle','the hiker had a legal problem','the hiker was standing in a queue','冰袋用于处理脚踝受伤。'),Q('Which sentence uses limping as an adjective?','The limping runner stopped by the track.','The runner limping yesterday yesterdayly.','The limping is a row of people.','limping 可作定语修饰 runner。'),Q('The base verb is?','limp','line','linger','limping 来自 limp。')]);
P('limy','Limy is formed from lime plus -y and describes soil or water containing abundant lime compounds.',C('limy.s1','园艺土壤','The gardener chose rosemary for the limy soil because the herb tolerates alkaline ground better than some plants.','园丁为富含石灰质的土壤选择了迷迭香，因为这种草本植物比一些植物更耐碱性土壤。','The gardener chose rosemary / for the limy soil / because the herb tolerates / alkaline ground better than some plants.','limy 修饰 soil，表示含石灰质较多；because 解释植物选择原因。','土壤富含石灰化合物，符合 s1。'),M('The sample was called limy even though tests found no lime or calcium compounds in the soil or water.','The sample was called limy because it contained abundant lime compounds.','没有石灰质成分的样品不应称为 limy。'),[Q('Limy soil contains a lot of?','lime or calcium compounds','linen fibres','metal lead','limy 指富含石灰质的。'),Q('Why was rosemary chosen for the limy soil?','it tolerates alkaline ground','it requires an acidic metal coating','it grows only in a laundry room','迷迭香较能适应碱性土壤。'),Q('Which phrase is natural?','limy water in a limestone region','limy cloth made of flax','limy language meaning “clear”','limy 可描述水或土壤的成分。'),Q('The suffix -y here means?','characterized by or containing lime','the final point in a list','the act of tying a rope','-y 构成“含有……的”形容词。')]);
P('line','Line comes from Latin linea, “linen thread or cord”; it has senses including a mark, a queue, a route or connection, written words, and arranging or covering.',C('line.s4','诗歌朗读','The actor repeated the final line of the poem slowly so the audience could hear the change in mood.','演员慢慢重复诗歌的最后一句，让观众听出情绪变化。','The actor repeated / the final line of the poem / slowly / so the audience could hear the change in mood.','line 指一行文字或演员说的一句台词；final 修饰 line，标出诗歌位置。','诗歌中的文字行符合 s4。'),M('The actor repeated the final line of the poem, a row of people waiting at a ticket counter.','The actor repeated the final written line of the poem.','诗歌文字行不是售票队伍。'),[Q('A straight line on a page is?','a long thin mark','a group of ancestors','a soft limp flower','line s1 指细长的标记。'),Q('People waiting for tickets may stand in a?','line','linen','linkage','line s2 可指排成一列的人。'),Q('“Please hold the line” refers to a?','telephone connection','written row of a poem','covering inside a tin','line s3 可指电话连接。'),Q('To line a tin with paper means?','cover its inside with a layer','stand in a row beside it','write a poem about it','line 作动词可表示给内部衬上一层。')]);
P('line up','Line up is a phrasal verb meaning to stand in a row while waiting or to arrange people or objects in a row.',C('line up.s1','展览入场','Visitors lined up outside the gallery before the doors opened for the new exhibition.','新展览开门前，访客在美术馆外排起了队。','Visitors lined up outside the gallery / before the doors opened / for the new exhibition.','lined up 为不及物短语动词，表示人们排队；before 从句指出排队的时间。','访客依次等候入场，符合 s1。'),M('Visitors lined up outside the gallery by scattering in every direction and refusing to form a row.','Visitors formed a row outside the gallery while waiting to enter.','四处散开且不排成队与 line up 相反。'),[Q('Visitors line up when they?','stand in a row while waiting','cover the inside of an object','praise an artist','line up 表示排队。'),Q('Where did visitors line up?','outside the gallery','inside the artist’s family tree','along the equator','访客在画廊外等候开门。'),Q('Which sentence is natural?','Please line up by the entrance.','Please line up the law to a new topic.','Please lined up the entrance tomorrow.','line up 可作排队或安排成行。'),Q('Line up can also mean to?','arrange objects in a row','let gas escape through a hole','make language lucid','该短语也可及物表示把物品排成一行。')]);
P('line-up','Line-up is the hyphenated noun from line up and names a set of performers or players; it can also mean a row of people shown to a witness.',C('line-up.s1','音乐节安排','The festival line-up includes three local bands and a violinist who will close the final evening.','音乐节演出阵容包括三支本地乐队和一位将在最后一晚压轴的小提琴家。','The festival line-up / includes three local bands / and a violinist / who will close the final evening.','line-up 作主语名词，指演出阵容；who 从句说明小提琴家的演出安排。','列出的艺人共同构成音乐节阵容，符合 s1。'),M('The festival line-up included no performers, players, or products presented together.','The festival line-up listed the performers scheduled to appear.','完全没有演出人员的名单不能叫演出阵容。'),[Q('A festival line-up is?','the set of performers scheduled to appear','a long thin mark on a page','the study of language','line-up 指演出阵容。'),Q('Who was included in the festival line-up?','three bands and a violinist','a witness and several suspects','only people waiting at the door','阵容列出乐队和小提琴家。'),Q('In a police investigation, a line-up can be?','a row of people shown to a witness for identification','a list of scheduled performers','a row of words in a poem','line-up 另可指辨认嫌疑人的一排人员。'),Q('How is the noun commonly distinguished from the verb?','line-up is a noun; line up is the verb','lineup is always a verb and line up a noun','they have unrelated spellings','名词常写 line-up，动词短语写 line up。')]);
P('lineage','Lineage comes from line plus -age and names the line of ancestors from whom a person descends.',C('lineage.s1','家族档案','The archivist traced the family’s lineage through parish records dating back to the early eighteenth century.','档案管理员通过可追溯到18世纪初的教区记录梳理了这个家族的世系。','The archivist traced the family’s lineage / through parish records / dating back / to the early eighteenth century.','lineage 作 traced 的宾语，指家族祖先传承；through 引出查证材料。','记录显示从祖先到后代的世系，符合 s1。'),M('The archivist traced the family’s lineage to a building’s roof rather than to any ancestors or descendants.','The archivist traced the family’s lineage through records of its ancestors.','建筑屋顶不是人的祖先或血统。'),[Q('A family’s lineage is its?','line of ancestors and descent','sequence of performers at a festival','thin sheet of metal','lineage 指家族世系。'),Q('How did the archivist trace the lineage?','through old parish records','by measuring the larynx','by standing in a ticket line','档案记录帮助追溯祖先。'),Q('Which phrase is natural?','trace a lineage back several generations','lineage the paper with cloth','a lineage is a line of waiting customers','lineage 可与 trace back 搭配。'),Q('Lineage is related to the word?','line','limp','linen','lineage 由 line 加 -age 构成。')]);
P('linear','Linear comes from Latin linearis, “belonging to a line,” and describes straight lines or a direct, step-by-step pattern.',C('linear.s1','数据分析','The scatterplot showed a linear trend: as study hours increased, test scores tended to rise at a steady rate.','散点图显示线性趋势：学习时长增加时，考试分数通常以稳定幅度上升。','The scatterplot showed a linear trend / as study hours increased / test scores tended to rise / at a steady rate.','linear 修饰 trend，表示变量之间呈直线式关系；冒号后给出该关系例子。','数据大致沿直线稳定变化，符合 s1。'),M('The report called the trend linear even though the plotted values formed a circle with no straight-line pattern.','The report called the trend circular because the values formed a loop.','圆形变化模式不是线性趋势。'),[Q('A linear pattern is associated with?','a straight line or direct progression','a family’s ancestors only','softness caused by injury','linear 指直线的或线性发展的。'),Q('What relationship appeared in the scatterplot?','scores rose steadily with study hours','scores formed a perfect circle','scores had no relation to study time','语境中的数据呈稳定线性趋势。'),Q('Which phrase is natural?','a linear increase over time','a linear curve that makes a perfect circle','linearly a paper with cloth','linear 常修饰 increase 或 trend。'),Q('The Latin source linearis means?','belonging to a line','made of linen','waiting in a row','linearis 与“线”有关。')]);
P('linen','Linen comes from Old English līn, “flax or linen,” probably an early borrowing related to Latin linum; it names flax cloth and household sheets or tablecloths.',C('linen.s1','餐桌布置','The host spread a clean linen tablecloth over the oak table before setting out the dishes.','主人在摆放餐具前，把一块干净的亚麻桌布铺在橡木桌上。','The host spread / a clean linen tablecloth / over the oak table / before setting out the dishes.','linen 作定语修饰 tablecloth，指亚麻制品；before 表示铺桌布先于摆餐具。','桌布由亚麻布制成，符合 s1。'),M('The tablecloth was linen even though it was made entirely from steel wire and contained no fabric.','The tablecloth was linen because it was woven from flax fibers.','金属丝制品不是亚麻布。'),[Q('Linen cloth is traditionally woven from?','flax fibers','metal lead','lime-rich soil','linen 指亚麻织物。'),Q('Bed linen can mean?','sheets and similar household cloths','the family line of ancestors','a row of people waiting','linen s2 指床单等家用布品。'),Q('Which phrase is natural?','a linen tablecloth','a linen tablecloth made of lead metal','linen a lawyer into court','linen 可作定语修饰桌布。'),Q('The Latin word connected to linen is?','linum, meaning flax','latus, meaning side','laudare, meaning praise','linen 的词源与拉丁语 linum 有关。')]);
P('liner','Liner is formed from line plus -er and can mean a large passenger ship, material covering an inside surface, or a regular-route passenger aircraft.',C('liner.s1','海上旅行','The ocean liner departed at dawn with passengers bound for several ports along the northern coast.','这艘远洋客轮黎明时启航，乘客将前往北部海岸的几个港口。','The ocean liner departed at dawn / with passengers / bound for several ports / along the northern coast.','liner 作主语名词，指长途载客船；bound for 说明航行目的地。','远洋客轮载客沿海航行，符合 s1。'),M('The ocean liner carried no passengers and was instead a thin plastic bag inside a wastebasket.','The ocean liner was a large ship carrying passengers on a long route.','垃圾桶内衬袋不是远洋客轮。'),[Q('An ocean liner is?','a large ship carrying passengers on long routes','a small piece of text that opens a web page','a type of fish','liner s1 指远洋客轮。'),Q('A bin liner is?','material or a bag lining the inside of a bin','a passenger ship','a regular-route aircraft','bin liner 指垃圾桶内衬袋。'),Q('An airliner is?','a passenger aircraft on a regular route','a line of ancestors','a fast fish related to cod','liner 也可出现在 airliner 中。'),Q('Which phrase is natural?','an ocean liner crossing the Atlantic','a liner that is a queue of people','a liner the window with paper','ocean liner 是常见搭配。')]);
P('ling','Ling as a fish name is probably related to long, describing its slender body; a separate British regional use names heather.',C('ling.s1','北大西洋渔业','The fishmonger salted the ling and packed it in wooden barrels for shipment from the northern port.','鱼贩把鳕形长体鱼腌制后装进木桶，从北部港口运走。','The fishmonger salted the ling / and packed it / in wooden barrels / for shipment from the northern port.','ling 作可数名词指一种细长的北大西洋鱼；the fishmonger 表明语境是鱼类。','捕获并腌制的海鱼符合 s1。'),M('The ling sold at the fish market was a purple heather shrub growing on a moor.','The ling sold at the fish market was a long-bodied marine fish.','鱼市售卖的鱼不是荒原上的石楠灌木。'),[Q('Ling in a fish market refers to?','a long-bodied marine fish related to cod','a type of underwear','a row of written words','ling s1 是鳕形鱼类。'),Q('A hillside covered with ling has?','heather shrubs','fish swimming over grass','linen sheets','ling 也可指石楠植物。'),Q('What clue indicates fish in the example?','the fishmonger salted it for shipment','the hills turned purple in August','the plants grew on a moor','盐腌、木桶和鱼贩提示鱼类义。'),Q('The fish name may relate to?','its long slender shape','the Latin word for praise','a line of family ancestors','鱼名可能与其细长体形有关。')]);
P('linger','Linger is a Germanic verb meaning stay longer than necessary; it also means remain faintly or take a long time to disappear.',C('linger.s2','火灾后检查','The smell of smoke lingered in the hallway long after the firefighters had left the building.','消防员离开大楼很久后，走廊里仍残留着烟味。','The smell of smoke lingered in the hallway / long after / the firefighters had left / the building.','linger 描述气味持续不散；long after 强调它超过火灾现场人员离开的时间仍存在。','气味微弱但长时间残留，符合 s2。'),M('The smoke smell lingered even though it disappeared immediately as soon as the firefighters entered.','The smoke smell faded gradually and remained for some time after the firefighters left.','立即消失与 linger 的持续不散相反。'),[Q('A smell that lingers?','remains faintly instead of going away quickly','is completely gone at once','is a person waiting in a queue','linger 可表示气味持续残留。'),Q('How long did the smoke smell remain?','long after firefighters left','only before the fire began','never at any time','烟味在消防员离开后仍然存在。'),Q('A person may linger after class by?','staying longer than necessary','leaving before class starts','covering a box with fabric','linger s1 指逗留。'),Q('Which phrase is natural?','memories linger in the mind','memories linger by disappearing instantly','linger a poem in a straight line','linger 可描述记忆或气味留存。')]);
P('lingerie','Lingerie came from French lingerie, originally goods made of linen, from old French linge “linen”; English uses it for women’s underwear.',C('lingerie.s1','服装店选购','The shop displayed lingerie made from soft cotton and silk in a separate section near the fitting rooms.','商店在试衣间附近的独立区域陈列了柔软棉质和丝质的女性内衣。','The shop displayed lingerie / made from soft cotton and silk / in a separate section / near the fitting rooms.','lingerie 作不可数名词，指女性内衣；made from 短语说明面料。','商店售卖的服装类别符合 s1。'),M('The store labeled its lingerie as a set of winter tires for a car.','The store labeled the garments as women’s underwear.','汽车轮胎不是女性内衣。'),[Q('Lingerie means?','underwear for women','a cloth covering a table only','a large passenger ship','lingerie 指女性内衣。'),Q('What materials were used for the lingerie?','soft cotton and silk','stone and steel','lime and soil','语境提到棉和丝质内衣。'),Q('Which phrase is natural?','a lingerie section in a clothing store','a lingerie ship crossing the ocean','lingerie the inside of a tin','lingerie 可作类别名词。'),Q('The French source lingerie originally related to?','linen goods and linen shops','the larynx','a direct line on a chart','该词源于法语 linen goods 一类的词。')]);
P('lingual','Lingual comes from Latin lingua, “tongue”; it describes the tongue in anatomy or speech, and as a noun may refer to a tongue-made sound.',C('lingual.s1','牙科治疗','The dentist numbed the lingual nerve before treating the tooth on the inner side of the jaw.','牙医在治疗下颌内侧的牙齿前，先麻醉了舌神经。','The dentist numbed the lingual nerve / before treating the tooth / on the inner side / of the jaw.','lingual 修饰 nerve，指与舌相关的神经；before 表示麻醉先于治疗。','语境中的舌神经符合解剖学 s1。'),M('The dentist numbed the lingual nerve, a nerve running through the patient’s knee.','The dentist numbed the lingual nerve associated with the tongue and mouth.','lingual nerve 位于口腔相关结构，并非膝部神经。'),[Q('A lingual nerve is related to the?','tongue','lawn','family lineage','lingual 的解剖义指与舌有关。'),Q('Why did the dentist numb the lingual nerve?','to prepare for treatment inside the jaw','to arrange a line-up of suspects','to launch a ship','治疗牙齿前麻醉口腔区域。'),Q('A lingual consonant is a sound made using the?','tongue','ocean liner','linen cloth','lingual 也可指用舌发出的语音。'),Q('The Latin source lingua means?','tongue','line','clear water','lingua 是“舌”的拉丁语词源。')]);
P('linguist','Linguist is formed from Latin lingua, “tongue,” and names a person trained in linguistics or skilled in several languages.',C('linguist.s1','方言研究','The linguist recorded speakers in the mountain villages and compared the word order of their dialects.','这位语言学家记录了山村居民的讲话，并比较他们方言中的词序。','The linguist recorded speakers / in the mountain villages / and compared the word order / of their dialects.','linguist 作主语名词，指研究语言的人；and 连接记录与比较两项研究工作。','系统研究方言结构符合 s1。'),M('The linguist compared dialects despite having no training in language study and refusing to listen to any speakers.','The linguist studied the dialects by recording and comparing how speakers used language.','既不懂语言研究也不采集语料，无法承担该项研究。'),[Q('A linguist is someone who?','studies language or is skilled in several languages','repairs ships on long routes','writes legal rules','linguist 指语言学家或通晓多种语言者。'),Q('What did the linguist compare?','word order in village dialects','the height of the mountain','the number of leaves on a tree','研究者比较不同方言的词序。'),Q('Which phrase is natural?','a linguist researching dialects','a linguist who studies only ocean tides','linguist the sentence in a row','linguist 可指从事方言研究的人。'),Q('Linguist is related to Latin lingua, meaning?','tongue','law','linen','lingua 与“舌、语言”有关。')]);
P('linguistic','Linguistic is formed from linguist/linguistics and means connected with language as a human system or with the academic field.',C('linguistic.s1','儿童发展','The assessment measured the child’s linguistic ability by asking her to describe a picture in her own words.','评估通过让孩子用自己的话描述一幅图，测量她的语言能力。','The assessment measured / the child’s linguistic ability / by asking her / to describe a picture in her own words.','linguistic 修饰 ability，表示语言能力；by 引出评估方法。','用语言描述图片测量语言能力，符合 s1。'),M('The assessment measured linguistic ability by asking the child to solve a puzzle without using or understanding language.','The assessment measured linguistic ability through a spoken description task.','完全不涉及语言的任务不能测量 linguistic ability。'),[Q('Linguistic ability concerns?','the ability to use or understand language','the strength of a roof beam','the clarity of a pool only','linguistic 指与语言有关的。'),Q('How did the test measure linguistic ability?','the child described a picture in words','the child stood in a line','the child measured soil lime','语言描述任务测量语言能力。'),Q('A linguistic study may examine?','language patterns and their use','a legal claim in court','a fish’s length only','linguistic 可修饰语言研究。'),Q('Which phrase is natural?','linguistic development in children','linguistic development with no language involved','a linguistically nerve','linguistic development 是自然搭配。')]);
P('linguistics','Linguistics is an uncountable noun for the scientific study of language and how language works.',C('linguistics.s1','大学课程','In the linguistics seminar, students compared how different languages mark tense and word order.','在语言学研讨课上，学生比较了不同语言如何标记时态和词序。','In the linguistics seminar / students compared / how different languages mark tense / and word order.','linguistics 是学科名，通常作单数使用；how 引出所研究的语言现象。','比较语言结构属于语言学研究，符合 s1。'),M('The course taught linguistics as the study of rocks and mineral formation.','The course taught linguistics as the scientific study of language.','岩石形成属于地质学，不是语言学。'),[Q('Linguistics is the study of?','language as a system','ocean liners','lawful court orders','linguistics 指语言学。'),Q('What did students compare in the seminar?','ways languages mark tense and word order','ways lawns are mowed','types of linen fabric','语言学课程比较不同语言结构。'),Q('Which sentence is standard?','Linguistics is a broad field.','Linguistics are a broad field in standard usage.','Linguistic studies is a type of fish.','学科名 linguistics 常作单数名词。'),Q('A person who studies linguistics is a?','linguist','liner','limp','linguist 是语言学研究者。')]);
P('lining','Lining is the noun from line and means material covering the inside of a coat, bag, or other object.',C('lining.s1','服装制作','The tailor replaced the torn silk lining inside the coat while leaving the outer wool fabric untouched.','裁缝更换了外套里破损的丝质内衬，同时保留了外层羊毛面料。','The tailor replaced / the torn silk lining / inside the coat / while leaving the outer wool fabric untouched.','lining 作 replaced 的宾语，指服装内部的衬里；inside the coat 表示其位置。','丝布覆盖外套内侧，符合 s1。'),M('The tailor replaced the coat’s lining by attaching silk only to its outer surface and leaving the inside bare.','The tailor added silk inside the coat as its lining.','只贴外面而让内部裸露，不符合 lining 的位置义。'),[Q('A coat lining is?','material covering its inside surface','a row of people waiting','a family’s line of descent','lining 指服装内衬。'),Q('What material was replaced inside the coat?','torn silk lining','the outer wool fabric','the coat’s family name','裁缝更换的是内侧丝质衬里。'),Q('Which phrase is natural?','a jacket with a warm lining','a jacket with a lining only on the outside','a lining that is a telephone connection','lining 通常位于衣物内部。'),Q('The verb related to lining can mean?','cover the inside of something with material','stand in a row','remain after a smell fades','line 也可作动词表示给内部衬上材料。')]);
P('link','Link is from Old English link, a ring in a chain; it now names a connection, chain part, or web control and can mean join things together.',C('link.s1','营养研究','Researchers found a link between regular breakfast and improved concentration in the morning classes.','研究人员发现，经常吃早餐与上午课程中的注意力改善之间存在关联。','Researchers found a link / between regular breakfast / and improved concentration / in the morning classes.','link 作宾语名词，between...and...连接两项相关因素。','研究发现早餐习惯与注意力有关，符合 s1。'),M('Researchers reported a link between breakfast and concentration even though their data showed no relationship at all.','Researchers reported no link because their data showed no association.','数据没有任何关系却宣称存在 link，前后矛盾。'),[Q('A link between two events is?','a relationship or connection','a soft cloth used for a wound','a line of people waiting','link s1 指联系或关联。'),Q('A link in a chain is?','one ring or connected part','the whole family ancestry','a telephone line only','link s2 可指链条的一个环节。'),Q('A web link is?','text or an image that opens another page','a linen shirt inside a coat','a law passed by government','link s3 指网页链接。'),Q('To link two towns is to?','join them physically or in a route','make each one unrelated','describe them as limpid','link 作动词表示连接。')]);


P('linkage','Linkage combines link with the noun-forming suffix -age and names a connection or the act of linking parts. ',C('linkage.s1','研究论文','The study found a linkage between sleep quality and memory scores, while noting that the association did not prove causation.','研究发现睡眠质量与记忆分数之间有关联，同时指出这种关联并不能证明因果关系。','The study found a linkage / between sleep quality and memory scores / while noting / that the association did not prove causation.','linkage 作名词，between...and...引出关联双方；后半句限制结论。','研究中的关联符合 linkage.s1。'),M('The report called the variables linked even though it found no connection between them.','The report should say there was no linkage because it found no connection.','没有联系却称有关联，语义自相矛盾。'),[Q('A linkage is a?','connection between things','stone bar over a doorway','soft fibre from clothing','linkage 表示连接或关联。'),Q('What relationship did the study examine?','sleep quality and memory scores','linen and lipstick prices','a lion and its mane','语境明确给出研究的两个变量。'),Q('Which claim is careful?','A linkage does not by itself prove causation.','A linkage always proves that one factor caused another.','A linkage is a type of floor covering.','相关联不等同于因果关系。'),Q('The suffix -age helps form a noun from?','link','lioness','liquidate','linkage 由 link 加名词后缀构成。')]);
P('linoleum','Linoleum is named from linseed oil and related material terms; it is a resilient sheet flooring, not a synonym for carpet.',C('linoleum.s1','旧屋翻修','The renovation crew lifted the cracked linoleum from the kitchen floor and found the original wooden boards underneath.','翻修工人从厨房地板上揭起开裂的油毡地板，发现下面是原来的木板。','The renovation crew lifted / the cracked linoleum / from the kitchen floor / and found the original wooden boards underneath.','linoleum 作不可数名词，作 lifted 的宾语；from 标明拆除位置。','可揭起的厨房片材地板符合 s1。'),M('They rolled up the linoleum as a thick wool carpet woven from yarn.','They removed the linoleum sheet flooring from the kitchen.','linoleum 是片材地板，不是羊毛编织地毯。'),[Q('Linoleum is used as?','sheet flooring','a doorway support beam','a cosmetic for lips','linoleum 指一种地面覆盖材料。'),Q('What was beneath the linoleum?','original wooden boards','a stone lintel','the kitchen ceiling','语境说地板片材下面是木板。'),Q('Which pairing is accurate?','cracked linoleum on a floor','linoleum lipstick on the lips','linoleum fish in the sea','linoleum 是地板材料。'),Q('The material in the passage was removed from the?','kitchen floor','doorway top','coat lining','语境位置是厨房地板。')]);
P('lint','Lint is recorded for loose fibres from cloth and for soft dressing material; in modern household use it commonly collects in a dryer filter.',C('lint.s1','洗衣房维护','After every load, Mara cleaned the dryer filter because a thick layer of lint had collected there.','每次烘干后，玛拉都会清理烘干机滤网，因为那里积了一层厚厚的绒屑。','After every load / Mara cleaned the dryer filter / because a thick layer of lint / had collected there.','lint 作不可数名词，作 had collected 的主语；because 引出清理原因。','烘干机滤网中的纤维屑符合 s1。'),M('The dryer filter was full of lint, meaning a row of people waiting for a bus.','The dryer filter was full of loose fibres from fabric.','滤网上的 lint 是织物纤维，不是排队的人。'),[Q('Lint in a dryer is?','tiny fibres from fabric','a large passenger ship','a bar over a doorway','家用语境中的 lint 是纤维绒屑。'),Q('Where had the lint collected?','in the dryer filter','on a lion’s mane','inside a glass of liquor','原句指出绒屑积在滤网上。'),Q('Which action removes lint?','cleaning the dryer filter','painting the lintel','lining a cup with linen','清理滤网可除去绒屑。'),Q('Lint is normally used here as a?','mass noun','plural verb','proper name','这里 lint 不可数。')]);
P('lintel','Lintel is a building term for the horizontal support placed across the top of a door, window, or other opening.',C('lintel.s1','古建筑测绘','A carved stone lintel spans the temple doorway, carrying the masonry above the entrance.','一根雕刻过的石过梁横跨神庙门口，承托入口上方的砖石结构。','A carved stone lintel / spans the temple doorway / carrying the masonry / above the entrance.','lintel 作主语名词，span 表示横跨；carrying 为伴随结构。','门洞上方承重横梁符合 s1。'),M('The lintel was installed as the stone threshold under people’s feet.','The lintel was set across the top of the doorway.','lintel 位于门洞上方，不是脚下门槛。'),[Q('A lintel is a support across the?','top of an opening','bottom of a shoe','inside of a coat','lintel 横跨门窗洞口的上方。'),Q('What material was the temple lintel made of?','stone','silk','liquid wax','语境明确为雕刻石材。'),Q('What did the lintel carry?','masonry above the entrance','a line of passengers','a lipstick tube','过梁承托上方砖石。'),Q('Lintel belongs chiefly to?','building terminology','weather forecasting','language study','lintel 是建筑术语。')]);
P('lion','Lion is a common animal name for a large wild cat; figuratively it can describe a brave or admired person.',C('lion.s1','野生动物观察','A lion rested in the grass while the guide kept the visitors inside the vehicle and at a safe distance.','一头狮子卧在草地上，向导让游客留在车内并保持安全距离。','A lion rested in the grass / while the guide kept the visitors / inside the vehicle / and at a safe distance.','lion 作主语名词；while 表示狮子休息时向导采取安全措施。','草地上的大型野猫符合动物义 s1。'),M('The guide called the resting lion a small domestic fish from the North Atlantic.','The guide identified the animal as a large wild cat.','狮子不是海鱼，也不是家养小动物。'),[Q('A lion is a?','large wild cat','female horse','small marine fish','lion 指大型猫科野生动物。'),Q('Where was the lion resting?','in the grass','in a doorway','inside a dryer','语境地点是草地。'),Q('A brave person may figuratively be called a?','lion','lintel','lira','lion 也可比喻勇敢的人。'),Q('Visitors stayed inside the?','vehicle','kitchen cupboard','line-up','语境中游客留在车内。')]);
P('lioness','Lioness adds the feminine suffix -ess to lion and means a female lion.',C('lioness.s1','草原生态','The lioness led the hunt at dusk, moving through the tall grass while the younger animals followed her.','黄昏时母狮带头捕猎，穿过高草，年轻的狮子跟在她身后。','The lioness led the hunt / at dusk / moving through the tall grass / while the younger animals followed her.','lioness 作主语；lead the hunt 表示带头行动。','带领捕猎的雌性狮子符合 s1。'),M('The zoo sign described the lioness as an adult male lion with a mane.','The zoo sign described the lioness as a female lion.','lioness 指母狮，不是有鬃毛的雄狮。'),[Q('A lioness is a?','female lion','male lion','young deer','lioness 表示母狮。'),Q('When did she lead the hunt?','at dusk','at noon in a classroom','during a ship launch','语境时间为黄昏。'),Q('The suffix -ess here marks?','a female animal','a verb tense','a material for flooring','lioness 由 lion 加表示女性的后缀构成。'),Q('Who followed the lioness?','younger animals','the kitchen workers','the linguists','原句说年轻动物跟随她。')]);
P('lip','Lip names the soft edge around the mouth; it can also mean the rim of a hollow object or, informally, rude answering-back.',C('lip.s1','意外克制','She bit her lip before answering the unfair accusation, choosing to remain calm until she had checked the facts.','面对不公正的指责，她回答前咬了咬嘴唇，选择先保持冷静，核实事实。','She bit her lip / before answering the unfair accusation / choosing to remain calm / until she had checked the facts.','lip 作身体部位名词；bite one’s lip 常表示克制情绪或话语。','嘴部动作及忍住回应符合身体义 s1。'),M('She bit her lip, meaning she tasted the rim of a cup rather than her mouth.','She bit the soft edge of her mouth while holding back a reaction.','语境中 bite one’s lip 是咬嘴唇，不是杯沿。'),[Q('A lip is normally part of the?','mouth','doorway roof','dryer filter','lip 通常指嘴唇。'),Q('Why did she bite her lip?','to stay calm before replying','to test the cup’s rim','to identify a lioness','语境表现她克制反应。'),Q('The lip of a cup means its?','top edge','handle','base','lip 也可指杯口沿。'),Q('Rude answering-back can informally be called?','lip','linen','lineage','lip 有口语义“顶嘴”。')]);
P('lip colour','Lip colour is a cosmetic product or shade applied to the lips; the two-word form is especially common in British English.',C('lip colour.s1','化妆品柜台','She tested a muted pink lip colour under the store lighting before choosing a shade that matched her natural skin tone.','她在店内灯光下试了柔和的粉色唇彩，然后选择了与自然肤色相配的色调。','She tested / a muted pink lip colour / under the store lighting / before choosing a shade.','lip colour 作名词短语，作 tested 的宾语；muted 描述低饱和色调。','涂在嘴唇上的化妆品符合 s1。'),M('The label said lip colour, but the product was a transparent floor varnish applied to wood.','The product was a coloured cosmetic intended for the lips.','唇彩用于嘴唇，不是木地板清漆。'),[Q('Lip colour is applied to the?','lips','floorboards','doorway lintel','名称说明它用于嘴唇。'),Q('Which shade did she test?','muted pink','bright green','clear stone grey','语境中试的是柔和粉色。'),Q('What did she do before choosing?','tested the colour under store lighting','removed linoleum from a floor','led a hunt at dusk','语境先试色再选择。'),Q('Lip colour is a type of?','cosmetic','wild cat','building support','唇彩属于化妆品。')]);
P('lipid','Lipid is a scientific term for a naturally occurring oily substance in living organisms, including fats and related compounds.',C('lipid.s1','生物化学课程','The lecturer explained that a lipid can store energy and form part of a cell membrane, then compared it with a carbohydrate.','讲师解释说，脂质可以储存能量并构成细胞膜的一部分，随后将它与碳水化合物作比较。','The lecturer explained / that a lipid can store energy / and form part of a cell membrane / then compared it with a carbohydrate.','lipid 作可数科学名词，that 引出解释内容；can 并列连接两项功能。','细胞和能量储存语境符合生物化学义 s1。'),M('The biology lesson defined a lipid as a stone beam placed above a doorway.','The lesson defined a lipid as an oily substance found in living things.','过梁是 lintel；lipid 是生物体中的脂质。'),[Q('A lipid is a natural?','oily substance in living things','stone support over a door','line of written words','lipid 是生物体内的油脂类物质。'),Q('What can a lipid help form?','part of a cell membrane','a temple doorway','a ship’s crew list','语境指出脂质可构成细胞膜。'),Q('Which subject commonly studies lipids?','biochemistry','architecture','cosmetics retail only','lipid 是科学术语。'),Q('The lecturer compared lipids with?','carbohydrates','lintels','lions','原句提到碳水化合物。')]);
P('lipread','Lipread is a verb meaning to understand speech by watching a speaker’s lip movements rather than relying on sound.',C('lipread.s1','无声课堂','When the microphone failed, Nia lipread the instructor from the front row and followed most of the demonstration.','麦克风失灵时，妮娅坐在前排，通过读唇理解讲师的话，并跟上了大部分演示。','When the microphone failed / Nia lipread the instructor / from the front row / and followed most of the demonstration.','lipread 作及物动词，宾语是 the instructor；when 引出听觉设备故障背景。','依靠唇部动作理解讲话符合 s1。'),M('Nia lipread the instructor by turning away and listening only to the broken microphone.','Nia watched the instructor’s mouth to understand the speech when the microphone failed.','转开视线并只靠失灵麦克风，与读唇相反。'),[Q('To lipread is to understand speech by watching?','lip movements','written lists','a ship’s tilt','lipread 指观察说话者嘴唇来理解话语。'),Q('Why did Nia lipread?','the microphone failed','the lights were too bright','she was studying a lion','语境原因是麦克风失灵。'),Q('Where was Nia sitting?','in the front row','under the doorway','on a ship at sea','原句说妮娅坐在前排。'),Q('Lipreading relies less on?','sound','visual movement','attention','读唇依赖视觉线索而非声音。')]);
P('lips','Lips is the regular plural of lip, the two soft parts surrounding the opening of the mouth.',C('lips.s1','冬日护理','After walking in the cold wind, his lips became dry, so he drank water and applied a protective balm.','在冷风中走了一段路后，他的嘴唇变干，于是喝了水并涂上防护润唇膏。','After walking in the cold wind / his lips became dry / so he drank water / and applied a protective balm.','lips 作复数主语；so 连接干燥情况与采取的护理措施。','嘴周围的两部分符合复数义 s1。'),M('His lips became dry, meaning the rims of two cups had lost moisture.','The two soft parts around his mouth became dry.','这里 lips 指人的嘴唇，不是杯口沿。'),[Q('Lips are the soft parts around the?','mouth','doorway','dryer','lips 指嘴周围的两部分。'),Q('What made his lips dry?','cold wind','a warm bath','a language lecture','语境提到冷风。'),Q('What did he apply?','protective balm','linoleum','lipstick to a lion','他涂了防护润唇膏。'),Q('Lips is the plural of?','lip','liner','lira','lip 的复数是 lips。')]);
P('lipstick','Lipstick is a coloured cosmetic for the lips; it may be uncountable for the substance or countable for one tube or stick.',C('lipstick.s1','日常化妆','Before the interview, Mei put on a little red lipstick and checked that none had marked the rim of her glass.','面试前，梅涂了一点红色口红，并检查玻璃杯口沿上没有留下痕迹。','Before the interview / Mei put on a little red lipstick / and checked / that none had marked the rim of her glass.','lipstick 在 a little 后作不可数物质名词；put on 表示涂抹。','涂在嘴唇上的有色化妆品符合 s1。'),M('She put on lipstick, meaning she used a liquid detergent to clean the glass.','She applied coloured cosmetic to her lips.','lipstick 是口红，不是清洁剂。'),[Q('Lipstick is used to colour the?','lips','floor','doorway','lipstick 用于装饰嘴唇。'),Q('How much lipstick did Mei put on?','a little','a whole doorway','two shiploads','a little 表明这里作不可数用法。'),Q('One tube may be called a?','lipstick','lip','lipread','一支口红可用可数名词 lipstick。'),Q('Where did she check for a mark?','the rim of her glass','the dryer filter','the lion’s mane','语境担心玻璃口沿沾上口红。')]);

P('liquefaction','Liquefaction is the noun for a process in which a substance becomes liquid; in earth science it also names loss of strength in water-saturated soil.',C('liquefaction.s1','天然气运输','Liquefaction of natural gas reduces its volume, allowing the fuel to be shipped across oceans in specialised tankers.','天然气液化会减小其体积，使这种燃料能够通过专用船舶运过海洋。','Liquefaction of natural gas / reduces its volume / allowing the fuel to be shipped / across oceans in specialised tankers.','liquefaction 作过程名词，of 引出被液化物；allowing 表示结果。','天然气转为液态以便运输符合 s1。'),M('The liquefaction process turned the gas into a solid block that could not flow.','Liquefaction changed the gas into a liquid and reduced its volume.','液化是转成液体，不是固体。'),[Q('Liquefaction is a process in which something becomes?','liquid','a doorway','a list','词义直接表示物质变成液体的过程。'),Q('What was liquefied in the example?','natural gas','a stone lintel','a lion’s mane','语境说天然气液化。'),Q('Why does liquefaction help shipping?','it reduces the gas volume','it makes the gas a solid','it turns fuel into a currency','液化天然气体积较小，便于运输。'),Q('Liquefaction is a?','noun for a process','plural of lip','type of wild cat','liquefaction 是过程名词。')]);
P('liquefy','Liquefy is formed from liquid with the verb-forming ending -fy and means to make something liquid or become liquid.',C('liquefy.s1','实验室加热','The technician warmed the wax gently until it began to liquefy, taking care not to overheat the sample.','技术员轻轻加热蜡，直到它开始液化，并小心避免样品过热。','The technician warmed the wax / gently / until it began to liquefy / taking care not to overheat the sample.','liquefy 作不及物动词，begin to 后接动词原形；until 引出变化发生的时点。','蜡受热开始变成液体符合 s1。'),M('The wax liquefied when it froze into a hard block.','The wax liquefied as it warmed and changed into a liquid.','冻结成硬块与液化相反。'),[Q('To liquefy wax is to make it?','liquid','a written list','a wild animal','liquefy 表示使变成液体。'),Q('What caused the wax to liquefy?','gentle warming','freezing','drying in cold air','语境中加热导致蜡液化。'),Q('Which form follows began to?','liquefy','liquefiedly','liquidness','begin to 后用动词原形。'),Q('The ending -fy helps form a?','verb','plural noun only','comparative adjective','liquefy 中 -fy 构成动词。')]);
P('liquid','Liquid can be a noun for a substance that flows, or an adjective meaning in liquid form; in finance, liquid assets can readily be converted to cash.',C('liquid.s1','科学课堂','At room temperature, water is a liquid, whereas ice is a solid and water vapour is a gas.','在室温下，水是液体，冰是固体，水蒸气则是气体。','At room temperature / water is a liquid / whereas ice is a solid / and water vapour is a gas.','liquid 作表语名词，与 solid、gas 并列；whereas 表示对比。','对物质状态的分类符合名词义 s1。'),M('The science chart classified flowing water at room temperature as a gas.','The chart classified water as a liquid, distinct from ice and vapour.','水在室温下是液体，不是气体。'),[Q('A liquid flows and is neither a solid nor a?','gas','list','lip','liquid 的科学定义区分固体和气体。'),Q('In the example, ice is a?','solid','liquid asset','gas','原句将冰与固体对应。'),Q('Liquid medicine is medicine in?','fluid form','a written list','a frozen block','形容词 liquid 表示液态的。'),Q('A liquid asset can readily be changed into?','cash','a doorway','a wild cat','金融义 liquid 表示易变现。')]);
P('liquidate','Liquidate means to sell assets to pay debts or close a business; a harsher figurative sense means to eliminate an opponent.',C('liquidate.s1','企业清算','Unable to repay its loans, the company liquidated its remaining stock and used the proceeds to pay creditors.','由于无力偿还贷款，公司变卖了剩余库存，并用所得款项偿还债权人。','Unable to repay its loans / the company liquidated its remaining stock / and used the proceeds / to pay creditors.','liquidate 作及物动词，stock 是宾语；to pay 表目的。','因债务而出售资产符合商业义 s1。'),M('The company liquidated its stock by buying more inventory and refusing to sell any assets.','The company sold assets to raise money for its creditors.','买入库存并拒绝出售与清算变卖资产相反。'),[Q('A company may liquidate assets to?','pay debts and close','form a line','colour its lips','商业义 liquidate 指变卖资产清偿债务。'),Q('What did the company liquidate?','remaining stock','the creditors','a stone doorway','语境中的宾语是剩余库存。'),Q('What did it use the proceeds for?','paying creditors','buying a lion','making lipstick','所得款用于偿还债权人。'),Q('A severe figurative use can mean to?','eliminate an opponent','turn wax into water','write a list','词条另有语气强烈的“清除对手”义。')]);
P('liquor','Liquor commonly means a strong alcoholic drink; in cooking it can also mean liquid produced during preparation.',C('liquor.s1','餐馆点单','The restaurant menu listed whisky and rum under liquor, and the server reminded guests that the drinks were for adults only.','餐厅菜单把威士忌和朗姆酒列在烈酒项下，服务员提醒客人这些饮品只供成年人饮用。','The restaurant menu listed / whisky and rum / under liquor / and the server reminded guests.','liquor 作类别名词；list A under B 表示将 A 列于 B 类别。','威士忌和朗姆酒属于烈酒，符合 s1。'),M('The menu classified whisky and rum as soft drinks containing no alcohol.','The menu listed them as strong alcoholic drinks.','威士忌和朗姆酒属于烈酒，不是无酒精软饮。'),[Q('Liquor commonly refers to?','strong alcoholic drinks','fruit juice','flooring material','常见义是烈酒。'),Q('Which drinks were listed under liquor?','whisky and rum','tea and milk','water and vapour','语境明确提到威士忌和朗姆酒。'),Q('Cooking liquor can mean liquid produced when?','food is cooked','a ship lists to port','a person speaks','词条还有烹饪过程中产生的液体义。'),Q('Who was reminded that the drinks were for adults?','guests','the lioness','the linguists','语境中的提醒对象是客人。')]);
P('lira','Lira is a currency unit formerly used in Italy and still used in Turkey; its traditional plural is lire.',C('lira.s1','旧菜单阅读','The historian translated an old Italian menu that listed a bowl of soup at five lire, the plural form of lira.','历史学家翻译了一份意大利旧菜单，上面一碗汤标价五里拉；lire 是 lira 的复数形式。','The historian translated an old Italian menu / that listed a bowl of soup / at five lire / the plural form of lira.','lira 作货币单位名词；five 后使用复数 lire。','旧意大利价格以里拉计价符合历史用法。'),M('The menu priced the soup at five lira, a unit of mass rather than currency.','The menu gave a price in lire, the traditional plural of the currency unit lira.','lira 是货币单位，不是质量单位。'),[Q('A lira is a?','currency unit','floor covering','wild cat','lira 指货币单位。'),Q('What was the old menu’s price?','five lire','five lintels','five litres of lipstick','语境说一碗汤五里拉。'),Q('Lire is traditionally the plural of?','lira','lip','liner','lire 是 lira 的复数形式。'),Q('Which countries have used or use the lira?','Italy and Turkey','Canada and Japan','Kenya and Brazil','词义说明曾用于意大利并仍用于土耳其。')]);
P('list','List is a series of written items or the verb to record or include items; as a verb it can also mean that a ship leans to one side.',C('list.s1','采购计划','Before leaving for the market, Omar made a list of vegetables, bread, and other items the household needed.','去市场前，奥马尔列了一份清单，写上家里需要的蔬菜、面包和其他物品。','Before leaving for the market / Omar made a list / of vegetables, bread, and other items / the household needed.','list 作名词，a list of 引出清单内容；before leaving 表示时间背景。','逐项记录采购物品符合名词义 s1。'),M('Omar made a list by deleting every item and leaving the page completely blank.','Omar wrote the items one after another on a list.','空白页面没有列出任何项目。'),[Q('A list is a series of?','names or items written one after another','fibres in a dryer','stones above a doorway','list 的名词义是一系列逐项记录的内容。'),Q('What did Omar list for the market?','vegetables and bread','lions and lionesses','whisky and rum only','语境举出了蔬菜和面包。'),Q('A ship may list when it?','leans to one side','turns into liquid','forms a queue','航海义 list 表示船身倾斜。'),Q('To list a person as a member means to?','include the person on a record','remove the person from all records','make the person lean','动词 list 可表示把某人列入名单。')]);
P('listen','Listen means to give attention to sounds or speech; listen to takes an object, and another use means to follow advice.',C('listen.s1','课堂交流','The students listened to the teacher’s explanation and wrote down the steps they would need for the experiment.','学生们听老师讲解，并记下实验所需的步骤。','The students listened / to the teacher’s explanation / and wrote down the steps / they would need for the experiment.','listen 不直接接宾语，通常用 listen to；and 连接听讲与记录。','专心听取老师讲解符合 s1。'),M('The students listened the teacher directly without the required preposition to.','The students listened to the teacher’s explanation.','listen 接听者或声音时通常要用 listen to。'),[Q('To listen is to give attention to?','a sound or what someone says','a written floor covering','a currency unit','listen 表示留心听声音或话语。'),Q('Which pattern is standard?','listen to the teacher','listen the teacher','listen at the teacher','listen 后接对象时通常使用 to。'),Q('To listen to advice can mean to?','follow or consider it','turn it into a liquid','put it on a list','listen to advice 表示听从或考虑建议。'),Q('What did the students write down?','steps for the experiment','the price of a lira','the lintel design','语境中他们记录实验步骤。')]);
P('listener','Listener is the agent noun from listen, naming a person who pays attention to speech, sounds, or a broadcast.',C('listener.s1','电台节目','The host thanked every listener who called in during the live programme and shared a question with the audience.','主持人感谢了直播节目中每位打电话参与并向听众分享问题的收听者。','The host thanked every listener / who called in during the live programme / and shared a question / with the audience.','listener 作 thanked 的宾语，指收听节目的人；who 引导定语从句。','收听并来电参与节目的个人符合 s1。'),M('The host thanked each listener, meaning every person who refused to hear the programme.','The host thanked each person who listened and called in.','拒绝收听与 listener 的含义相反。'),[Q('A listener is someone who?','pays attention to sounds or speech','repairs a doorway','makes a currency list','listener 指听声音、讲话或广播的人。'),Q('What did some listeners do?','called in with questions','removed floor tiles','led a hunt','语境提到听众打电话参与并提问。'),Q('Listener is formed from which verb?','listen','line','liquidate','listener 由 listen 加施事后缀构成。'),Q('Which word stresses one person hearing a broadcast?','listener','audience as a whole','lintel','listener 强调具体收听者。')]);
P('listless','Listless describes a person who lacks energy or interest; context distinguishes physical tiredness from emotional disengagement.',C('listless.s1','病房探望','The child lay listless in bed with a fever, barely lifting his head when his friends brought him a book.','孩子发烧后无精打采地躺在床上，朋友们给他带书来时，他几乎抬不起头。','The child lay listless in bed / with a fever / barely lifting his head / when his friends brought him a book.','listless 作表语形容词，描述孩子缺少精力；barely 表示几乎不。','发烧后体力不振符合 s1。'),M('The feverish child was listless, eagerly running around with unlimited energy.','The feverish child was weak and lacked energy.','精力旺盛地奔跑与 listless 的疲倦状态相反。'),[Q('Someone listless lacks?','energy or interest','a doorway beam','currency','listless 表示没精神或没兴趣。'),Q('Why was the child listless?','he had a fever','he had just won a race','he was giving a lecture','语境说明孩子发烧。'),Q('Which sense describes boredom rather than tiredness?','showing little interest in surroundings','a ship leaning to one side','a volume measure','listless 也可描述心理上的兴味索然。'),Q('How did the child respond to the book?','he barely lifted his head','he led a hunt','he liquefied it','语境写他几乎没抬头。')]);
P('liter','Liter is a metric unit of volume equal to one thousand millilitres; litre is also common in British spelling.',C('liter.s1','厨房量取','The recipe calls for one liter of water, so Jo filled the measuring jug to its marked one-liter line.','食谱需要一升水，于是乔把量杯加到标有一升刻度的位置。','The recipe calls for one liter / of water / so Jo filled the measuring jug / to its marked one-liter line.','liter 作容量单位名词；one 后用单数，of 引出液体。','以公制升计量水量符合 s1。'),M('The recipe asked for one liter of water, meaning one thousand kilograms by weight.','The recipe used liter as a unit of volume equal to 1,000 millilitres.','liter 是容量单位，不是千克质量单位。'),[Q('One liter equals?','1,000 millilitres','100 kilometres','one thousand grams in every case','升是容量单位，等于 1,000 毫升。'),Q('What did Jo measure?','water','lipstick','linoleum','语境中她量的是水。'),Q('What line did Jo use?','the one-liter mark on a jug','a line of written dialogue','a ship’s waterline','量杯上有一升刻度。'),Q('Two liters refers to two measures of?','volume','temperature','distance','liter 计量体积。')]);
P('literacy','Literacy means the ability to read and write; by extension it means knowledge and skill in a field such as digital literacy.',C('literacy.s1','成人教育','The community programme improved adult literacy by offering evening classes in reading, writing, and practical form filling.','社区项目通过开设阅读、写作和实际填表夜校，提高了成人识字能力。','The community programme improved adult literacy / by offering evening classes / in reading, writing / and practical form filling.','literacy 作 improved 的宾语；by offering 说明实现方式。','阅读和写作能力符合基本义 s1。'),M('The programme improved literacy by teaching adults to avoid reading and writing altogether.','It improved the ability to read and write through evening classes.','拒绝读写不会提高 literacy。'),[Q('Basic literacy is the ability to?','read and write','build a lintel','identify a currency','literacy 基本义是读写能力。'),Q('Which is an extended kind of literacy?','digital literacy','lion literacy','liquor literacy','literacy 还可表示某领域的知识技能。'),Q('How did the programme teach adults?','evening classes','a wildlife hunt','ship repair','语境说明通过夜校开展课程。'),Q('Which word is the opposite of basic literacy?','illiteracy','lineage','liquefaction','illiteracy 表示缺乏读写能力。')]);
P('literal','Literal means using a word’s basic meaning rather than a figurative one; it can also describe word-for-word translation or something actually true.',C('literal.s1','阅读理解','The teacher asked students to separate the literal meaning of the phrase from the metaphorical image used in the poem.','老师要求学生把短语的字面意思与诗中使用的比喻意象区分开来。','The teacher asked students / to separate the literal meaning / from the metaphorical image / used in the poem.','literal 修饰 meaning；separate A from B 表示区分两种解释。','与比喻义相对的基本词义符合 s1。'),M('The teacher called a metaphorical image literal even though it was not meant in its basic sense.','The teacher distinguished the basic meaning from the metaphorical image.','比喻义并非 literal 的字面义。'),[Q('A literal meaning is the?','basic meaning of the words','opposite of a dictionary entry','sound of a ship’s engine','literal meaning 指词语的基本字面义。'),Q('A literal translation is made?','word for word','only with pictures','without using words','literal 也可指逐字翻译。'),Q('Which use means true without exaggeration?','a literal fact','a figurative comparison','a fictional animal','literal 另有“确实的”一义。'),Q('What did students distinguish from literal meaning?','a metaphorical image','the class schedule','a litre measure','语境将字面义与比喻意象对比。')]);
P('literally','Literally means according to the exact meaning of words; informal speech also uses it as an intensifier, often hyperbolically.',C('literally.s1','澄清误会','When Sam said he had literally taken the instructions apart, he meant that he had separated the pages, not merely ignored them.','萨姆说自己确实把说明拆开了时，他指的是把纸页分开，并不是仅仅没理会说明。','When Sam said / he had literally taken the instructions apart / he meant / that he had separated the pages.','literally 修饰 take apart，强调按词语真实字面含义发生。','拆开纸页是实际动作，符合 s1。'),M('Sam said he literally separated the pages, but he had only thought about doing so.','Sam actually separated the pages as the words literally state.','只有想法而未行动，不能称为按字面真的拆开。'),[Q('Literally can mean?','according to the exact words','in a figurative way only','without paying attention','literally 的基本义是按字面。'),Q('In casual speech literally may be used to?','emphasize something as an intensifier','name a unit of volume','describe a doorway beam','口语中它有夸张强调用法。'),Q('What did Sam actually do?','separated the instruction pages','wrote a poem','measured water','语境解释为把纸页分开。'),Q('Which contrast is correct?','literally versus figuratively','listener versus audience','lithe versus lint','literally 与 figuratively 意义相对。')]);
P('literalness','Literalness is the quality of following exact, word-for-word meaning rather than figurative or idiomatic language.',C('literalness.s1','字幕翻译','The subtitle’s literalness preserved every word of the joke, but the result sounded stiff and lost the humour for local viewers.','字幕的逐字直译保留了笑话中的每个词，但成品听起来生硬，令当地观众感受不到幽默。','The subtitle’s literalness / preserved every word of the joke / but the result sounded stiff / and lost the humour.','literalness 作主语名词；but 引出逐字翻译的负面效果。','逐字处理造成生硬的性质符合 s1。'),M('The translation showed literalness by freely replacing every word with an unrelated idiom.','It showed literalness by sticking closely to the source wording.','自由替换成无关习语不符合逐字忠实。'),[Q('Literalness is a quality of being?','strictly word for word','highly energetic','easy to convert to cash','literalness 指严格按字面逐字处理。'),Q('What effect did it have on the subtitle?','it sounded stiff','it became a wild animal','it measured a litre','语境提到成品听起来生硬。'),Q('Literalness may help a translator preserve?','exact wording','a figurative joke at any cost','nothing from the source','逐字忠实有时有助于保留准确措辞。'),Q('Which approach instead uses idioms freely?','free idiomatic translation','strict literalness','copying each word exactly','习语化翻译与严格逐字方式相对。')]);
P('literary','Literary describes writing, books, and artistic language; it can also mean characteristic of formal writing or knowledgeable about literature.',C('literary.s1','评论写作','She writes literary criticism for a journal, examining how novels use voice, imagery, and narrative structure.','她为期刊撰写文学评论，分析小说如何运用叙述声音、意象和叙事结构。','She writes literary criticism / for a journal / examining how novels use voice / imagery, and narrative structure.','literary 修饰 criticism，说明评论对象与文学作品有关。','分析小说作品的评论符合 s1。'),M('Her literary criticism reviewed only car engines and never discussed books or writing.','Her criticism discussed novels and their artistic techniques.','汽车发动机不是该语境中的文学作品。'),[Q('Literary criticism is connected with?','books and writing','dryer maintenance','currency exchange','literary 可表示与文学作品相关。'),Q('What did she examine in novels?','voice and imagery','lip colour and lipstick','ship lists and lintels','语境列出小说的艺术手法。'),Q('A literary style may be typical of?','formal or artistic writing','a marine fish','a metric volume','literary 也可描述偏正式、艺术化的文风。'),Q('A literary visitor might be?','knowledgeable about literature','unable to read or write','a doorway support','literary 还有熟悉文学的含义。')]);
P('literate','Literate means able to read and write; it can also mean knowledgeable or skilled in a particular subject.',C('literate.s1','社区调查','The survey found that most adults in the district were literate and could read the public health notices without assistance.','调查发现，该地区大多数成年人具备读写能力，能够自行阅读公共卫生告示。','The survey found / that most adults in the district were literate / and could read / the public health notices without assistance.','literate 作表语形容词；could read 解释其读写能力。','能阅读告示体现基本读写能力 s1。'),M('The survey called adults literate even though they could not recognize or read any words.','It described them as able to read and write.','完全不能识字与 literate 基本义相反。'),[Q('A literate person can?','read and write','only calculate litres','repair a lintel','literate 基本义是有读写能力的。'),Q('A computer-literate worker has?','skill using computers','a skill in lion hunting','a litre of liquid','literate 可表示在某领域有知识技能。'),Q('Which word is the opposite of literate?','illiterate','literary','lithe','illiterate 指不识字的。'),Q('What could surveyed adults read?','public health notices','a lion’s thoughts','the weather in a doorway','语境举出公共卫生告示。')]);
P('literature','Literature refers to written works valued for artistic quality and to published writing on a particular subject.',C('literature.s1','大学课程','The course introduced Russian literature through short stories and novels, then asked students to discuss how each work represented migration.','课程通过短篇小说和长篇小说介绍俄罗斯文学，随后要求学生讨论每部作品如何呈现迁徙。','The course introduced Russian literature / through short stories and novels / then asked students to discuss / how each work represented migration.','literature 作不可数名词，指文学作品总体；through 表示课程选材方式。','小说和故事组成的文学作品符合 s1。'),M('The course studied Russian literature by examining only kitchen flooring and never reading a text.','The course examined Russian written works such as stories and novels.','地板材料不是文学作品。'),[Q('Literature can mean works valued for?','artistic quality','their ability to store cash','their use as a doorway beam','文学作品通常以艺术价值为特点。'),Q('What works did the course use?','short stories and novels','lint and linen','whisky and rum','语境列出短篇小说和长篇小说。'),Q('Literature is usually used as a?','uncountable noun','plural verb','currency unit','表示文学总体时 literature 不可数。'),Q('Published material on a subject may also be called?','literature','lipread','lithosphere','literature 也可指某主题的文献资料。')]);
P('lithe','Lithe describes a body that bends easily and moves gracefully; it can also describe smooth, graceful movement.',C('lithe.s1','舞蹈排练','The lithe dancer folded into a deep stretch without strain, then rose smoothly as the music changed tempo.','这位柔韧的舞者毫不费力地做出深度拉伸，随后随着音乐变速平稳起身。','The lithe dancer folded into a deep stretch / without strain / then rose smoothly / as the music changed tempo.','lithe 修饰 dancer，强调身体柔韧；without strain 表示动作轻松。','身体灵活易弯的舞者符合 s1。'),M('The dancer was described as lithe despite being unable to bend or move freely.','The dancer was flexible and able to bend easily.','无法弯曲和活动与 lithe 的柔韧义相反。'),[Q('A lithe person is?','flexible and able to bend easily','unable to read','a unit of volume','lithe 描写柔韧灵活的身体。'),Q('How did the dancer rise?','smoothly','with a rigid stumble','by listing a ship','语境写她平稳起身。'),Q('Lithe can also describe?','graceful movement','an exact translation','a strong alcoholic drink','该词也能形容轻盈优雅的动作。'),Q('Which person best fits lithe?','a flexible gymnast','a rigid statue','a listless patient','柔韧体操运动员符合该形容词。')]);
P('lithification','Lithification is the geological compaction and cementation that turns loose sediment into sedimentary rock.',C('lithification.s1','地质野外调查','Over geological time, pressure compacted the sand and minerals cemented its grains; this lithification produced a sandstone layer.','经过漫长地质时期，压力压实沙粒，矿物质又胶结颗粒；这一成岩作用形成了砂岩层。','Over geological time / pressure compacted the sand / and minerals cemented its grains / this lithification produced a sandstone layer.','lithification 作过程名词；compact 与 cement 描述沉积物变岩石的两步。','沉积物压实胶结成岩符合地质学义 s1。'),M('The geologist defined lithification as the melting of sandstone into liquid lava.','Lithification compacts and cements sediment into sedimentary rock.','成岩作用不是把砂岩熔化成熔岩。'),[Q('Lithification changes sediment into?','sedimentary rock','a strong drink','a written list','lithification 指沉积物成岩过程。'),Q('What two actions are involved?','compaction and cementing','freezing and evaporation only','reading and writing','源义包括压实和胶结。'),Q('Lithification belongs to?','geology','cosmetics','broadcasting','这是地质学术语。'),Q('What rock formed in the passage?','sandstone','lipstick','linoleum','语境说形成砂岩层。')]);
P('lithograph','Lithograph names a picture produced by lithography and can also be a verb meaning to print by that process.',C('lithograph.s1','美术馆藏品','The gallery acquired a nineteenth-century lithograph whose fine city streets and rooftops remained clear despite the print’s age.','美术馆收藏了一幅十九世纪石版画，尽管年代久远，画中细致的街道和屋顶仍清晰可见。','The gallery acquired / a nineteenth-century lithograph / whose fine city streets and rooftops / remained clear despite the print’s age.','lithograph 作可数名词，作 acquired 的宾语；whose 引出画作细节。','一幅以石版印制的图像符合名词义 s1。'),M('The gallery displayed a lithograph, meaning a live broadcast of a radio listener.','The gallery displayed a picture printed by lithography.','石版画是印刷图像，不是广播。'),[Q('A lithograph is a?','picture printed by lithography','unit of liquid volume','female lion','lithograph 可数名词指石版画。'),Q('Where was the lithograph acquired?','at a gallery','in a dryer','at a liquor store','语境说美术馆收藏了作品。'),Q('As a verb, lithograph means to?','print by the lithographic process','make a person literate','leave rubbish in a park','该词也可作动词表示石版印刷。'),Q('What remained clear in the old print?','streets and rooftops','a cup’s lip','a list of currencies','语境提到街道和屋顶仍清晰。')]);
P('lithographic','Lithographic is the adjective from lithography and means related to or produced by that printing process.',C('lithographic.s1','印刷工艺介绍','Lithographic printing reproduced the artist’s fine lines on a metal plate, allowing the same image to be printed repeatedly.','石版印刷把艺术家的细线图案复制到金属板上，使同一图像能够反复印制。','Lithographic printing / reproduced the artist’s fine lines / on a metal plate / allowing the same image to be printed repeatedly.','lithographic 作定语修饰 printing；allowing 表示工艺结果。','与石版印刷工艺相关的形容词义符合 s1。'),M('The museum called the digital audio recording lithographic even though it involved no printing process.','The museum used lithographic for a print made by that process.','纯音频录制与石版印刷无关。'),[Q('Lithographic means related to?','lithography','literacy','liquor','该形容词指与石版印刷有关。'),Q('What did the process reproduce?','fine lines on a metal plate','a litre of water','a lion’s mane','语境说复制细线图案。'),Q('Lithographic modifies which noun in the example?','printing','audience','currency','句中是 lithographic printing。'),Q('Which item may be lithographic?','a print made by lithography','a glass of cooking liquor','a written grocery list','石版印制的画作可称 lithographic。')]);
P('lithography','Lithography is a printmaking process in which ink adheres to image areas on a stone or metal plate.',C('lithography.s1','版画展览','The museum label explained that lithography transfers an image from a prepared stone or metal plate onto paper.','博物馆说明牌解释说，石版印刷会把经过处理的石板或金属板上的图像转印到纸上。','The museum label explained / that lithography transfers an image / from a prepared stone or metal plate / onto paper.','lithography 作不可数工艺名词；that 引出说明内容。','由石或金属版转印图像符合 s1。'),M('The label described lithography as a process in which ink avoids the image area and cannot print it.','Lithography prints from a prepared stone or metal plate onto paper.','版面图像区域接受油墨并完成印制，并非避开图像。'),[Q('Lithography is a process for?','printing images from a plate','measuring liquid volume','writing a shopping list','lithography 指一种印刷工艺。'),Q('What may carry the prepared image?','a stone or metal plate','a lion’s mane','a linen shirt','词义说明使用石板或金属板。'),Q('Where is the image transferred?','onto paper','into cooking liquor','under a doorway lintel','印刷时图像转印到纸上。'),Q('Photolithography is related but more specific in?','chip manufacturing','wildlife ecology','adult reading classes','现代芯片制造使用更专门的 photolithography。')]);
P('lithosphere','Lithosphere is the hard outer layer of Earth, including the crust and uppermost mantle; it is divided into slowly moving plates.',C('lithosphere.s1','地震科学','Earthquakes can occur when plates of the lithosphere move and stress builds up along their boundaries.','当岩石圈板块移动、边界处应力不断积累时，就可能发生地震。','Earthquakes can occur / when plates of the lithosphere move / and stress builds up / along their boundaries.','lithosphere 作 of 短语中的名词；when 引出地震发生条件。','地壳与上地幔组成的硬外层符合 s1。'),M('The textbook defined the lithosphere as the layer of liquid clouds above the atmosphere.','It defined the lithosphere as Earth’s rigid outer layer.','岩石圈是地球硬外层，不是大气层上方的液态云。'),[Q('The lithosphere includes the crust and?','upper mantle','ocean water only','clouds','岩石圈包括地壳和上部地幔。'),Q('What can move within the lithosphere?','large plates','lipstick tubes','lists of words','地球外层由移动的板块构成。'),Q('Movement along plate boundaries may cause?','earthquakes','literacy','liquefaction of clouds','语境将板块移动与地震联系。'),Q('The adjective for something of this layer is?','lithospheric','literary','listless','lithospheric 是相关形容词。')]);
P('lithospheric','Lithospheric is the adjective meaning of or relating to the lithosphere, especially in plate tectonics.',C('lithospheric.s1','板块构造课','A lithospheric plate can carry oceanic crust and continental crust as it moves slowly across the mantle.','岩石圈板块在地幔上缓慢移动时，可以承载大洋地壳和大陆地壳。','A lithospheric plate / can carry oceanic crust and continental crust / as it moves slowly / across the mantle.','lithospheric 修饰 plate，表示属于岩石圈的板块。','板块构造语境中的 lithospheric plate 符合 s1。'),M('A lithospheric plate was described as a soft cosmetic applied to the lips.','It is a rigid plate belonging to Earth’s lithosphere.','岩石圈板块是地质结构，不是化妆品。'),[Q('Lithospheric means related to the?','lithosphere','literature','lips','lithospheric 指岩石圈的。'),Q('What can a lithospheric plate carry?','oceanic and continental crust','a litre of milk','a group of puppies','语境说明它可承载两类地壳。'),Q('Which field often uses this adjective?','plate tectonics','cosmetics','radio broadcasting','板块构造研究常用该词。'),Q('How does the plate move in the example?','slowly across the mantle','rapidly through the atmosphere','in a line through a market','原句说板块在地幔上缓慢移动。')]);
P('litigate','Litigate is a formal verb meaning to take a dispute to court so that a legal decision can be made.',C('litigate.s1','合同纠纷','After mediation failed, the supplier and the retailer decided to litigate the contract dispute in court.','调解失败后，供应商和零售商决定就合同纠纷提起诉讼。','After mediation failed / the supplier and the retailer decided to litigate / the contract dispute / in court.','litigate 作动词；decide to 后接原形，不及物用法可省略宾语。','双方将争议提交法院裁决符合 s1。'),M('The parties chose to litigate by settling privately and avoiding any court proceeding.','They chose to take their dispute to court.','私下解决并避免法院程序与 litigate 相反。'),[Q('To litigate is to take a dispute to?','court','a market list','a printing plate','litigate 表示通过诉讼解决争端。'),Q('What was the dispute about?','a contract','a lion’s diet','lip colour','语境说双方有合同纠纷。'),Q('What happened before they litigated?','mediation failed','the case was printed','the supplier became a listener','原句指出调解失败后起诉。'),Q('Litigate is generally a?','formal verb','currency unit','plural noun for lips','litigate 是正式用语动词。')]);
P('litigation','Litigation is the process of bringing or defending a case in court; it is normally an uncountable noun.',C('litigation.s1','公司法律事务','The firm threatened litigation after negotiations broke down, but both sides later reached a settlement before trial.','谈判破裂后，公司威胁提起诉讼，但双方后来在开庭前达成和解。','The firm threatened litigation / after negotiations broke down / but both sides later reached a settlement / before trial.','litigation 作不可数名词，作 threatened 的宾语；but 转折到庭前和解。','以法院诉讼处理案件的过程符合 s1。'),M('The firm threatened litigation while insisting that it would never take any case to court.','It threatened possible court proceedings after talks failed.','litigation 指诉讼程序，与绝不诉诸法院的说法矛盾。'),[Q('Litigation is the process of?','taking a case to court','printing an image from stone','measuring water','litigation 指诉讼过程。'),Q('What followed the failed negotiations?','a threat of litigation','a lion hunt','a literacy class','语境写谈判失败后威胁诉讼。'),Q('The parties settled before?','trial','the lithosphere formed','the menu was translated','原句说在开庭前达成和解。'),Q('Litigation is usually?','uncountable','a plural adjective','a unit of volume','litigation 通常作不可数名词。')]);
P('litter','Litter can mean rubbish left in public, a group of young animals born together, or material in a pet tray; as a verb it means leave rubbish or cover an area with things.',C('litter.s1','公园清洁','After the festival, volunteers collected litter from the paths and placed the bottles and wrappers in recycling bags.','节庆结束后，志愿者从小路上收集垃圾，并把瓶子和包装纸放进回收袋。','After the festival / volunteers collected litter from the paths / and placed the bottles and wrappers / in recycling bags.','litter 作不可数名词，指公共场所遗留垃圾；from 标明收集地点。','小路上的瓶子和包装纸符合环境义 s1。'),M('The volunteers collected litter, meaning a litter of newborn puppies, from the festival paths.','They collected rubbish left on the paths.','语境是公共道路上的废弃物，不是一窝幼崽。'),[Q('Litter in a park is?','rubbish left lying in public','a strong alcoholic drink','a hard Earth layer','litter 的环境义是散落的垃圾。'),Q('A litter of puppies means?','a group born together','rubbish in a park','a set of printed pictures','litter 也指同窝出生的一群幼崽。'),Q('Cat litter is material used in a?','pet toilet tray','doorway support','measuring jug','猫砂用于宠物如厕托盘。'),Q('To litter a beach means to?','leave it covered with rubbish','clean it completely','turn it into sedimentary rock','动词 litter 表示乱丢垃圾或使遍布垃圾。')]);
P('little','Little describes small size or youth; as a determiner it means not much or a small amount, and as an adverb it can mean to a small degree or for a short time.',C('little.s1','儿童文学','A little boy waited by the library door, holding a book that was almost as large as his school bag.','一个小男孩抱着一本几乎和书包一样大的书，在图书馆门口等候。','A little boy waited / by the library door / holding a book / almost as large as his school bag.','little 作定语形容词，表示年幼或体形小；holding 为伴随动作。','年幼的男孩符合 s1。'),M('A little boy was described as a very old adult many times larger than everyone around him.','He was a young or small boy.','描述强调年幼或小，不是年长且巨大。'),[Q('A little boy is usually?','young or small','a large wild cat','a unit of volume','little 可表示小或年幼。'),Q('Little water left means?','not much water remains','a large amount remains','the water became solid','little 与不可数名词搭配可表示几乎没有。'),Q('Add a little salt means add?','a small amount','no salt at all','a large bag of salt','a little 表示肯定的少量。'),Q('Wait a little while means wait?','for a short time','for several years','until the room is empty','little 作副词可表示时间短。')]);
P('little-known','Little-known combines little with the past participle known and describes something known by only a few people.',C('little-known.s1','人物传记','The little-known author published several novels in her home country, but few readers outside Poland had heard of her.','这位鲜为人知的作家在本国出版了几部小说，但波兰以外很少有读者听说过她。','The little-known author / published several novels / in her home country / but few readers outside Poland had heard of her.','little-known 作复合形容词修饰 author；连字符常用于名词前。','在本国有作品但海外少有人知，符合 s1。'),M('The little-known author was famous to nearly everyone around the world.','Only a small number of people knew the author.','全球几乎人人知晓与 little-known 相反。'),[Q('Little-known means known by?','only a few people','almost everyone','no living person under any condition','该形容词表示鲜为人知。'),Q('What had the author published?','several novels','a scientific unit','a ship’s cargo','语境提到她出版了几部小说。'),Q('Where had few readers heard of her?','outside Poland','inside the library only','on the moon','原句限定波兰以外的读者很少了解她。'),Q('Where is the hyphenated adjective placed here?','before the noun author','after a question mark','between two verbs','little-known 作名词前定语。')]);
P('livable','Livable means pleasant or safe enough for people to live in; liveable is a common British spelling variant.',C('livable.s1','旧公寓改造','The owners repaired the heating and removed the damp before calling the flat livable enough for a family to move into.','房主修好了暖气并处理了潮湿问题，之后才认为这套公寓足够宜居，适合一家人搬入。','The owners repaired the heating / and removed the damp / before calling the flat livable / enough for a family to move into.','livable 作宾语补足语形容词；enough 后接不定式说明适宜程度。','适合居住的公寓符合 s1。'),M('The flat was livable even though it had no safe structure, heat, or protection from rain.','The repaired flat was safe and pleasant enough to live in.','缺少安全结构和基本遮蔽，不符合宜居条件。'),[Q('A livable home is?','safe or pleasant enough to live in','a place no one can inhabit','a farm animal','livable 表示宜居的。'),Q('What did the owners repair?','the heating','the lithosphere','the lipstick','语境提到修理暖气。'),Q('What did they remove from the flat?','damp','a lizard','a loan','他们处理了房屋潮湿问题。'),Q('Which spelling is also common in British English?','liveable','liverable','livingable','英式常用拼写 liveable。')]);
P('live','Live is a verb meaning reside, remain alive, or spend life in a way; as an adjective it can mean broadcast as it happens or carrying electricity.',C('live.s1','租房生活','They live in a small flat near the station, where they can walk to work and take the train to visit family.','他们住在车站附近的一套小公寓里，可以步行上班，也能乘火车探望家人。','They live in a small flat / near the station / where they can walk to work / and take the train to visit family.','live 作居住义动词，地点由 in 引出；where 引导地点从句。','在某地有住所符合 s1。'),M('They live in a flat means they have no home there and are only visiting for one hour.','They have their home in the flat.','live in 表示居住，并非短暂停留。'),[Q('They live in a flat means they?','have their home there','are broadcast on television','carry electricity','live 的一义是居住。'),Q('Plants live means they?','are alive or remain alive','own a house','form a line','live 作动词还可表示活着。'),Q('To live simply means to?','spend life in an uncomplicated way','broadcast a concert','carry an electric current','live 可表示以某种方式度过生活。'),Q('A live match is?','broadcast as it happens','a written transcript only','an unpowered device','形容词 live 可指现场直播。')]);
P('live-action','Live-action describes a film or scene made with living performers and real sets rather than animation.',C('live-action.s1','电影改编','The studio’s live-action version used actors and practical sets while keeping the story’s original ending.','制片公司的真人电影版使用演员和实景布置，同时保留了故事原本的结局。','The studio’s live-action version / used actors and practical sets / while keeping / the story’s original ending.','live-action 作复合形容词修饰 version；while 引出同步保留的特点。','真人演员和实景而非动画，符合 s1。'),M('The studio called its hand-drawn cartoon live-action despite using no performers or real sets.','The studio filmed actors on practical sets for its live-action version.','纯手绘动画不是 live-action。'),[Q('A live-action film uses?','living performers and real sets','only animated drawings','a printed shopping list','live-action 指真人出演和真实布景。'),Q('What did the studio keep?','the original ending','the original cartoon drawings only','a farm’s livestock','语境说保留故事结局。'),Q('Which adjective contrasts with live-action here?','animated','lively','livable','live-action 与动画形式相对。'),Q('Live in live-action is pronounced like?','the adjective meaning happening in real time','the verb meaning reside','the noun meaning a living room','live-action 中 live 读 /laɪv/。')]);
P('livelihood','Livelihood is the work, income, or means by which a person or household supports life.',C('livelihood.s1','渔村生计','Fishing is the main livelihood for many families in the village, providing both income and food throughout the year.','捕鱼是村里许多家庭的主要生计，一年四季为他们提供收入和食物。','Fishing is the main livelihood / for many families in the village / providing both income and food / throughout the year.','livelihood 作表语名词；providing 补充说明其作用。','捕鱼作为谋生来源符合 s1。'),M('Fishing was their livelihood although it provided neither work, income, food, nor support.','Fishing supplied work and income on which the families depended.','没有任何收入或生活支持就不能称为生计来源。'),[Q('A livelihood is a means of?','earning a living','decorating lips','printing a lithograph','livelihood 指谋生方式或来源。'),Q('What did the flood destroy in the second sense?','the household’s means of support','a doorway lintel','a live broadcast','livelihood 还可指维持家庭生活的依靠。'),Q('Livelihood differs from job because it stresses?','dependence for support','a temporary hobby only','a person’s shoe size','livelihood 更强调生存所依赖的收入或来源。'),Q('Fishing provided the families with?','income and food','only a court case','a list of books','语境指出捕鱼提供收入和食物。')]);
P('liveliness','Liveliness is the energy and cheerful activity that makes a person or place feel animated.',C('liveliness.s1','集市见闻','Visitors were surprised by the liveliness of the morning market, where sellers called out and neighbours greeted one another.','游客对早市的热闹活力感到惊讶，摊贩高声招呼，邻里互相问候。','Visitors were surprised / by the liveliness of the morning market / where sellers called out / and neighbours greeted one another.','liveliness 作介词 by 的宾语；where 引导地点从句解释热闹场景。','叫卖和邻里交谈构成活力氛围，符合 s1。'),M('The liveliness of the market meant it was silent, empty, and completely inactive.','The market’s activity and cheerful energy made it lively.','寂静空荡与热闹活跃相反。'),[Q('Liveliness means energy and?','cheerful activity','lack of movement','a unit of volume','liveliness 表示活力与生气。'),Q('What surprised the visitors?','the morning market’s lively atmosphere','a silent empty station','a lizard in a jar','语境说游客惊讶于早市氛围。'),Q('Which word is the base adjective?','lively','liver','livery','liveliness 来源于形容词 lively。'),Q('What were sellers doing?','calling out','reading a legal verdict','measuring a liter','摊贩在高声招呼。')]);
P('lively','Lively describes energetic people or places and can also mean bright, quick, and full of interest, as in a lively discussion.',C('lively.s1','早晨课堂','The children were lively this morning, asking questions, moving between activity stations, and laughing with their classmates.','孩子们今天早上很活跃，不停提问、在活动区之间走动，还和同学们一起大笑。','The children were lively / this morning / asking questions / and laughing with their classmates.','lively 作表语形容词；现在分词短语举例说明孩子们的活跃表现。','提问、活动和欢笑符合精力充沛义 s1。'),M('The children were lively, sitting motionless and showing no energy or interest.','They were energetic and active in class.','一动不动且毫无活力与 lively 相反。'),[Q('Lively children are usually?','full of energy','unable to move','a type of livestock','lively 可形容精力充沛的人。'),Q('A lively discussion is?','bright and full of interest','silent and empty','a written loan contract','该词也可形容有趣热烈的讨论。'),Q('What did the children ask?','questions','for a court trial','for a lintel','语境中孩子们在提问。'),Q('Which noun names the quality of being lively?','liveliness','livelihood','liver','liveliness 是名词形式。')]);
P('liven','Liven is a transitive verb meaning to make something more interesting or lively, often in the phrase liven up.',C('liven.s1','派对筹备','She livened the party with a playlist of familiar songs, and soon even the shy guests were dancing.','她用一份熟悉歌曲的播放列表让派对活跃起来，很快连害羞的客人也开始跳舞。','She livened the party / with a playlist of familiar songs / and soon / even the shy guests were dancing.','liven 作及物动词，party 是宾语；with 引出使气氛活跃的手段。','音乐让派对变得更有趣，符合 s1。'),M('She livened the party by removing all music, conversation, and activity.','She made the party more lively by playing familiar songs.','去除音乐与活动会使派对冷清，而非活跃。'),[Q('To liven something is to make it?','more interesting or lively','less active and dull','a unit of volume','liven 表示使更活跃有趣。'),Q('What did she use to liven the party?','familiar songs','a legal hearing','a load of soil','语境提到播放熟悉歌曲。'),Q('Which phrasal form is common?','liven up','live on to','load out of','常见搭配是 liven up。'),Q('What happened to shy guests?','they began dancing','they left the country','they became livestock','气氛活跃后害羞的客人也跳舞。')]);
P('liver','Liver is the large organ that processes substances in the body and helps digestion; the animal organ is also eaten as food.',C('liver.s1','健康教育','The nurse explained that the liver helps process substances in the blood and supports digestion, so persistent pain should be checked.','护士解释说，肝脏有助于处理血液中的物质并支持消化，因此持续疼痛应接受检查。','The nurse explained / that the liver helps process substances in the blood / and supports digestion / so persistent pain should be checked.','liver 作主语名词；helps 并列支配 process 与 support 两个动词。','身体器官及其功能符合医学义 s1。'),M('The nurse explained that the liver is a bone whose only job is to pump air into the lungs.','The liver is an organ that processes substances and helps digestion.','肝脏是器官，不是骨骼或肺部气泵。'),[Q('The liver is a large body?','organ','currency unit','piece of flooring','liver 指人体器官。'),Q('What does the liver help with?','processing blood substances and digestion','printing images','measuring volume','该器官参与代谢并帮助消化。'),Q('Chicken liver in a recipe refers to?','the animal organ used as food','a live broadcast','a legal dispute','liver 也指作为食物的动物肝脏。'),Q('Who explained the organ’s role?','the nurse','the lizard','the loan officer','语境中护士进行说明。')]);
P('livery','Livery is a distinctive uniform worn by servants or drivers working for one owner or organisation.',C('livery.s1','庄园礼仪','The estate’s drivers wore green livery with the family emblem stitched on each jacket sleeve.','庄园司机穿着绿色制服，每件夹克袖子上都绣有家族徽章。','The estate’s drivers wore green livery / with the family emblem / stitched on each jacket sleeve.','livery 作不可数名词，指统一制服；with 短语补充制服装饰。','司机按雇主要求穿着带徽章的制服符合 s1。'),M('The drivers wore livery, meaning plain clothes with no identifying uniform or employer connection.','They wore a distinctive uniform identifying the estate.','没有识别特征的便服与 livery 相反。'),[Q('Livery is a special?','uniform linked to an owner or organisation','farm animal','currency loan','livery 指雇主或机构识别制服。'),Q('What colour was the drivers’ livery?','green','pink','transparent','语境明确说绿色。'),Q('Where was the emblem stitched?','on each jacket sleeve','inside a loaf','on a courtroom floor','徽章绣在夹克袖子上。'),Q('Livery in this passage is worn by?','drivers','lizards','listeners','语境中的穿制服者是司机。')]);
P('livestock','Livestock collectively means farm animals kept for food, materials, or other products; it is normally uncountable and has no plural -s.',C('livestock.s1','农场盘点','The farm keeps cattle, sheep, and other livestock in separate fields, and the animals are brought in for checks each spring.','农场把牛、羊和其他牲畜分栏饲养，每年春天将它们赶来检查。','The farm keeps cattle, sheep, and other livestock / in separate fields / and the animals are brought in / for checks each spring.','livestock 作集合名词，通常不可数且不加复数 -s；后句用 animals 指具体个体。','农场饲养的牛羊等动物符合 s1。'),M('The farmer counted three livestocks in the field as though livestock took a regular plural ending.','The farmer counted three livestock animals in the field.','livestock 通常不可数，不用 three livestocks。'),[Q('Livestock means farm?','animals such as cattle and sheep','rooms where guests sit','written literary works','livestock 指牛羊等农场牲畜。'),Q('Why are animals kept as livestock?','to produce food or other goods','to act in a live-action film only','to provide a court verdict','该词指为生产食物或其他产品而饲养的动物。'),Q('Which form is standard?','some livestock','some livestocks','a livestock of','livestock 通常不加复数 -s。'),Q('What does the farm keep?','cattle and sheep','lips and lint','lithographs and lira','语境列出牛和羊。')]);
P('living','Living can name the way someone earns money or act as an adjective meaning alive or existing now.',C('living.s1','职业选择','Teaching provides a good living for her family, and she also enjoys helping young students learn to read.','教书为她的家庭提供了不错的生计，她也喜欢帮助年轻学生学习阅读。','Teaching provides a good living / for her family / and she also enjoys / helping young students learn to read.','living 作名词，a good living 指良好生计；provides 的主语是 teaching。','工作收入支撑家庭生活，符合 s1 名词义。'),M('Teaching provided a good living, meaning the family had no income or means of support.','Teaching gave the family a way to earn money and support themselves.','有不错的生计说明有生活来源，并非没有收入。'),[Q('A good living can mean?','a way to earn money for life','a type of reptile','a room for guests','living 名词可指生计。'),Q('A living language is?','still spoken and in use','a language carved on a dead stone only','a unit of volume','living 作形容词可表示仍在使用或存在。'),Q('What work provided the family’s living?','teaching','lithography','raising only lipstick','语境说教书提供生计。'),Q('Which phrase means earn enough to support oneself?','make a living','make a lintel','make a lizard','make a living 表示谋生。')]);
P('living-room','Living-room is the room in a home where people sit, talk, and relax; it may also be the main room used to receive guests.',C('living-room.s1','家庭日常','After dinner, the family moved from the kitchen to the living-room, where they sat together and talked about the day.','晚饭后，一家人从厨房来到客厅，坐在一起聊起当天的事情。','After dinner / the family moved from the kitchen / to the living-room / where they sat together and talked.','living-room 作地点名词；where 引导从句说明家人到客厅后做什么。','家人休息交谈的房间符合 s1。'),M('They moved to the living-room, which was actually the room where the family cooked every meal.','They moved to the room used for sitting and relaxing.','厨房是做饭的房间，living-room 是起居休息处。'),[Q('A living-room is where people often?','sit and relax','cook every meal','store livestock','客厅通常用于坐着休息交谈。'),Q('Where did the family go after dinner?','from the kitchen to the living-room','from the garden to a court','from the farm to a ship','语境给出晚饭后去客厅。'),Q('A living-room may be used for?','receiving guests','measuring liquids','printing lithographs','客厅也可作为接待客人的主要房间。'),Q('Which is another common name in British English?','sitting room','liver room','loam room','英式常说 sitting room 或 lounge。')]);
P('lizard','Lizard is a small cold-blooded reptile, usually with four short legs and a long tail; the word can also refer to leather made from its skin.',C('lizard.s1','岩石观察','A small lizard sunned itself on the warm rock, then darted into a crack when the hikers came closer.','一只小蜥蜴在温暖的岩石上晒太阳，徒步者靠近时，它便迅速钻进了裂缝。','A small lizard sunned itself / on the warm rock / then darted into a crack / when the hikers came closer.','lizard 作主语名词；then 表示先晒太阳后逃入裂缝。','岩石上晒太阳的爬行动物符合 s1。'),M('The hikers saw a lizard, a warm-blooded bird with feathers and wings.','They saw a small cold-blooded reptile.','蜥蜴是爬行动物，不是有羽毛的鸟。'),[Q('A lizard is a type of?','reptile','currency','bread','lizard 指爬行动物。'),Q('What did the lizard do on the rock?','sunned itself','printed a picture','paid a loan','语境说它在岩石上晒太阳。'),Q('Lizard can also refer to leather made from?','its skin','linoleum','a lion’s mane','词条还有蜥蜴皮革的义项。'),Q('What did the animal do when hikers approached?','darted into a crack','started a live broadcast','listed to port','它迅速钻入岩石裂缝。')]);
P('load','Load can mean a carried amount, a quantity of work or responsibility, or the verb putting goods into a vehicle; informally a lot of something.',C('load.s1','码头装运','The truck carried a heavy load of timber to the harbour, where workers transferred the boards onto a ship.','卡车把一大批木材运到港口，工人们在那里将木板转装到船上。','The truck carried a heavy load / of timber / to the harbour / where workers transferred the boards onto a ship.','load 作 carried 的宾语，指载货量；of 引出货物内容。','卡车运载的木材符合名词义 s1。'),M('The truck’s load consisted of nothing because its cargo filled the vehicle completely.','The truck carried a heavy amount of timber as its load.','载荷为空与装有大量木材矛盾。'),[Q('A truck’s load can be?','something heavy that it carries','the room where guests sit','a printed picture','load 名词指运载的货物或数量。'),Q('A teaching load means an amount of?','work or responsibility','soil on a farm','money borrowed from a bank','load 还可表示工作量或责任。'),Q('To load boxes onto a ship is to?','put them aboard','take them off','turn them into liquid','动词 load 表示把货物装上运输工具。'),Q('Loads of work means?','a lot of work','no work at all','one small task','loads of 是口语“大量”。')]);
P('loaded','Loaded means carrying a full amount, often used with with; informally it can also mean pregnant.',C('loaded.s1','农场运输','The cart was loaded with hay before sunrise, so the farmer secured the cover and checked that nothing could fall onto the road.','日出前，手推车装满了干草，于是农场主固定好盖布，并检查是否有东西会掉到路上。','The cart was loaded with hay / before sunrise / so the farmer secured the cover / and checked the load.','loaded 作表语形容词；be loaded with 表示装满某物。','装满干草的车符合 s1。'),M('The cart was loaded with hay, meaning it was completely empty and carried nothing.','The cart was full of hay.','装满干草与空车相反。'),[Q('Loaded with hay means?','carrying a full amount of hay','having no hay','growing hay in a field','loaded with 表示装满。'),Q('When was the cart loaded?','before sunrise','after the trial','during a broadcast','语境时间为日出之前。'),Q('What did the farmer secure?','the cover','a living-room wall','the lizard’s tail','农场主固定了盖布。'),Q('Loaded can informally also mean?','pregnant','made of lithography','able to read','该词另有口语“怀孕的”义。')]);
P('loaf','Loaf is a shaped piece of bread; it can also name a shaped mass of food or, as a verb, mean spend time idly.',C('loaf.s1','面包店购物','At the bakery, Rosa bought a loaf of bread and asked the baker to slice it before she carried it home.','罗莎在面包店买了一条面包，并请面包师切片后再带回家。','At the bakery / Rosa bought a loaf of bread / and asked the baker to slice it / before she carried it home.','loaf 作可数名词；a loaf of bread 表示一条面包。','烘焙成形的整条面包符合 s1。'),M('Rosa bought a loaf of bread, meaning a handful of loose flour with no baked shape.','She bought one shaped piece of baked bread.','loaf 指成形面包，不是未烘焙的散面粉。'),[Q('A loaf is one shaped piece of?','bread','currency','flooring','loaf 常指一条成形面包。'),Q('A meat loaf is a shaped mass of?','food such as meat','paper instructions','a wild cat','loaf 也可指其他成形食物。'),Q('To loaf around means to?','spend time lazily','bake bread quickly','take a case to court','动词 loaf around 表示闲散消磨时间。'),Q('What did Rosa ask the baker to do?','slice the bread','load the ship','measure one liter','她请面包师把面包切片。')]);
P('loam','Loam is fertile crumbly soil that retains moisture while draining well; as a less common verb, it means cover or fill with loam.',C('loam.s1','园艺整地','The gardener mixed compost into sandy loam, creating soil that held enough moisture for tomatoes but did not stay waterlogged.','园丁把堆肥混入沙壤土，形成既能为番茄保水又不会积水的土壤。','The gardener mixed compost / into sandy loam / creating soil that held enough moisture / but did not stay waterlogged.','loam 作不可数土壤名词；creating 补充说明混合后的效果。','保水且排水良好的土质符合 s1。'),M('The gardener chose loam because it stayed flooded and could not drain any water.','The loam held moisture while still draining well.','壤土的特点是保水同时排水，并非持续积水。'),[Q('Loam is a type of?','rich crumbly soil','strong alcoholic drink','currency','loam 指肥沃疏松的土壤。'),Q('What did the gardener mix into it?','compost','lipstick','a court document','语境说混入堆肥。'),Q('Good loam holds moisture but also?','drains well','stays flooded','turns into a lizard','壤土保水但排水也较好。'),Q('As a verb, to loam a bed means to?','cover or fill it with loam','remove all soil','plant a loaf','动词 loam 指用壤土覆盖或填充。')]);
P('loan','Loan is money lent and due to be repaid, or an object lent temporarily; it can also be a verb meaning lend.',C('loan.s1','小企业融资','The bank gave Hana a loan to open her shop, and she compared the repayment terms before signing the agreement.','银行给哈娜一笔贷款帮助她开店，她在签署协议前比较了还款条款。','The bank gave Hana a loan / to open her shop / and she compared the repayment terms / before signing the agreement.','loan 作可数名词，a loan 指借款；to open 表示资金用途。','银行借出的、需偿还的钱符合 s1。'),M('Hana received a loan from the bank that she was told never had to be repaid.','She borrowed money under terms requiring repayment.','loan 通常要求偿还，与永不归还的说法不符。'),[Q('A bank loan is money that must be?','paid back','thrown away','printed from a stone','loan 名词指需要偿还的借款。'),Q('An object on loan is?','borrowed temporarily','owned permanently by the borrower','a group of farm animals','on loan 表示暂借或借展。'),Q('To loan a book is to?','lend it to someone','keep it forever','turn it into a list','loan 可作动词表示借出。'),Q('What did Hana compare before signing?','repayment terms','lizard leather','living-room furniture only','语境说她比较还款条款。')]);

})();
